// src/components/SvgFlow.js
import React, { useRef, useEffect } from "react";
import * as d3 from "d3";

function parseCodeToFlowchart(code = "") {
  const nodes = [];
  const edges = [];

  if (!code || !code.trim()) return { nodes, edges };

  // Parse function declaration
  const fnMatch = code.match(/function\s+(\w+)\s*\(([^)]*)\)/) || code.match(/const\s+(\w+)\s*=\s*\(([^)]*)\)\s*=>/);
  const fnName = fnMatch ? fnMatch[1] : "fn";
  const param = fnMatch ? fnMatch[2].trim() : "";

  // Start node
  nodes.push({ 
    id: "start", 
    label: "Start", 
    type: "terminal",
    shape: "stadium" 
  });

  // Function declaration node
  nodes.push({
    id: "function",
    label: `Function: ${fnName}(${param})`,
    type: "process",
    shape: "rectangle"
  });
  edges.push({ from: "start", to: "function" });

  // Input parameter node
  if (param) {
    nodes.push({ 
      id: "input", 
      label: `Input parameter: ${param}`, 
      type: "io",
      shape: "parallelogram" 
    });
    edges.push({ from: "function", to: "input" });
  }

  // Decision node for if condition
  const hasCondition = /if\s*\(/.test(code);
  if (hasCondition) {
    const condMatch = code.match(/if\s*\(([^)]+)\)/);
    const condition = condMatch ? condMatch[1].trim() : "condition";
    
    nodes.push({ 
      id: "decision", 
      label: `Check if ${condition}`, 
      type: "decision",
      shape: "diamond" 
    });
    edges.push({ 
      from: param ? "input" : "function", 
      to: "decision" 
    });

    // True path
    const trueLogMatch = code.match(/if\s*\([^{]*\)\s*{([^}]*)}/);
    const trueLog = trueLogMatch ? 
      trueLogMatch[1].trim().replace(/console\.log\(|\)/g, '').replace(/["']/g, '') : 
      "true branch";
    
    nodes.push({ 
      id: "true_process", 
      label: `Print: ${trueLog}`, 
      type: "io",
      shape: "parallelogram" 
    });
    edges.push({ 
      from: "decision", 
      to: "true_process", 
      label: "Yes" 
    });

    // False path
    const falseLogMatch = code.match(/else\s*{([^}]*)}/);
    const falseLog = falseLogMatch ? 
      falseLogMatch[1].trim().replace(/console\.log\(|\)/g, '').replace(/["']/g, '') : 
      "false branch";

    nodes.push({ 
      id: "false_process", 
      label: `Print: ${falseLog}`, 
      type: "io",
      shape: "parallelogram" 
    });
    edges.push({ 
      from: "decision", 
      to: "false_process", 
      label: "No" 
    });

    // Connect both paths to end
    edges.push({ from: "true_process", to: "end" });
    edges.push({ from: "false_process", to: "end" });
  } else {
    // If no condition, connect directly to end
    edges.push({ from: param ? "input" : "function", to: "end" });
  }

  // End node
  nodes.push({ 
    id: "end", 
    label: "End", 
    type: "terminal",
    shape: "stadium" 
  });

  return { nodes, edges };
}

function SvgFlow({ graph, code, onNodeClick }) {
  const svgRef = useRef();

  useEffect(() => {
    let g;
    
    // Use graph if provided, otherwise parse code
    if (graph && graph.nodes && graph.nodes.length) {
      g = graph;
      // Normalize the graph - ensure nodes have 'label' property
      g.nodes = g.nodes.map(node => ({
        ...node,
        label: node.label || node.text || 'Unknown',
        shape: node.shape || (
          node.type === 'decision' ? 'diamond' : 
          node.type === 'loop' ? 'diamond' :
          node.type === 'start' ? 'terminal' :
          node.type === 'end' ? 'terminal' :
          node.type === 'input' ? 'parallelogram' :
          node.type === 'output' ? 'parallelogram' :
          node.type === 'function' ? 'rectangle' :
          node.type === 'return' ? 'parallelogram' : 'rectangle'
        )
      }));
    } else if (code) {
      g = parseCodeToFlowchart(code);
    } else {
      g = { nodes: [], edges: [] };
    }
    
    const svgEl = d3.select(svgRef.current);
    svgEl.selectAll("*").remove(); // clear old diagram

    if (!g.nodes || !g.nodes.length) {
      // show placeholder text
      svgEl
        .append("text")
        .attr("x", 20)
        .attr("y", 30)
        .attr("fill", "#6b7280")
        .style("font-size", "14px")
        .text('No flowchart yet — click "Generate Flowchart"');
      return;
    }

    const containerWidth = svgRef.current.parentElement?.clientWidth || 900;
    const width = 900;
    const height = 800;
    const nodeWidth = 180;
    const nodeHeight = 60;
    const verticalGap = 100;
    const horizontalGap = 200;

    svgEl.attr("width", "100%").attr("height", height);
    svgEl.attr("viewBox", `0 0 ${width} ${height}`).attr("preserveAspectRatio", "xMidYMin meet");

    // Simple hierarchical layout
    const layers = [];
    const nodeMap = new Map(g.nodes.map(n => [n.id, n]));
    const visited = new Set();
    
    // Build layers (BFS approach)
    const queue = [{ nodeId: g.nodes[0]?.id, layer: 0, position: 0 }];
    const layerNodes = new Map();
    
    while (queue.length > 0) {
      const { nodeId, layer, position } = queue.shift();
      if (!nodeId || visited.has(nodeId)) continue;
      
      const node = nodeMap.get(nodeId);
      if (!node) continue;
      
      visited.add(nodeId);
      
      if (!layerNodes.has(layer)) {
        layerNodes.set(layer, []);
      }
      layerNodes.get(layer).push({ node, position });
      
      // Find children
      const outgoingEdges = g.edges.filter(e => e.from === nodeId && !visited.has(e.to));
      
      if (node.type === 'decision' || node.type === 'loop') {
        const yesEdge = outgoingEdges.find(e => e.label === 'Yes');
        const noEdge = outgoingEdges.find(e => e.label === 'No');
        
        if (yesEdge) queue.push({ nodeId: yesEdge.to, layer: layer + 1, position: position + 1 });
        if (noEdge) queue.push({ nodeId: noEdge.to, layer: layer + 1, position: position - 1 });
        
        outgoingEdges.filter(e => e !== yesEdge && e !== noEdge && e.label !== 'Loop back')
          .forEach(edge => queue.push({ nodeId: edge.to, layer: layer + 1, position }));
      } else {
        outgoingEdges.forEach(edge => {
          if (edge.label !== 'Loop back') {
            queue.push({ nodeId: edge.to, layer: layer + 1, position });
          }
        });
      }
    }
    
    // Position nodes based on layers
    const centerX = width / 2;
    const startY = 60;
    
    layerNodes.forEach((nodesInLayer, layer) => {
      const y = startY + layer * verticalGap;
      const layerWidth = (nodesInLayer.length - 1) * horizontalGap;
      const startX = centerX - layerWidth / 2;
      
      nodesInLayer.forEach((item, index) => {
        const node = item.node;
        node.x = nodesInLayer.length === 1 ? centerX : startX + index * horizontalGap;
        node.y = y;
        node.label = node.label || node.text;
      });
    });

    // markers for arrows
    svgEl
      .append("defs")
      .append("marker")
      .attr("id", "arrow")
      .attr("viewBox", "0 0 10 10")
      .attr("refX", 10)
      .attr("refY", 5)
      .attr("markerWidth", 7)
      .attr("markerHeight", 7)
      .attr("orient", "auto")
      .append("path")
      .attr("d", "M 0 0 L 10 5 L 0 10 z")
      .attr("fill", "#1e293b");

    // draw edges
    const edgeGroup = svgEl.append("g").attr("class", "edges");
    g.edges.forEach((e) => {
      const from = g.nodes.find((n) => n.id === e.from);
      const to = g.nodes.find((n) => n.id === e.to);
      if (!from || !to) return;

      const fromBottom = { x: from.x, y: from.y + nodeHeight / 2 };
      const toTop = { x: to.x, y: to.y - nodeHeight / 2 };

      let path;
      const dx = toTop.x - fromBottom.x;
      const dy = toTop.y - fromBottom.y;
      
      // For loop back edges (going upward)
      if (dy < 0) {
        const offset = 100;
        const leftX = Math.min(from.x, to.x) - offset;
        path = `M ${fromBottom.x},${fromBottom.y} 
                L ${fromBottom.x},${fromBottom.y + 20}
                L ${leftX},${fromBottom.y + 20}
                L ${leftX},${toTop.y - 20}
                L ${toTop.x},${toTop.y - 20}
                L ${toTop.x},${toTop.y}`;
      } else if (Math.abs(dx) < 10) {
        // Straight line for vertical connections
        path = `M ${fromBottom.x} ${fromBottom.y} L ${toTop.x} ${toTop.y}`;
      } else {
        // Smooth curve for branching
        const controlY = (fromBottom.y + toTop.y) / 2;
        path = `M ${fromBottom.x} ${fromBottom.y} 
                C ${fromBottom.x} ${controlY}, ${toTop.x} ${controlY}, ${toTop.x} ${toTop.y}`;
      }

      edgeGroup
        .append("path")
        .attr("d", path)
        .attr("fill", "none")
        .attr("stroke", "#475569")
        .attr("stroke-width", 2.5)
        .attr("marker-end", "url(#arrow)");

      if (e.label) {
        let labelX, labelY;
        
        // For loop back edges
        if (dy < 0) {
          const offset = 100;
          const leftX = Math.min(from.x, to.x) - offset;
          labelX = leftX - 25;
          labelY = (fromBottom.y + toTop.y) / 2;
        }
        // For vertical connections
        else if (Math.abs(dx) < 10) {
          labelX = fromBottom.x + 50;
          labelY = (fromBottom.y + toTop.y) / 2;
        }
        // For curved connections (branches) - position closer to decision
        else {
          // Position label near the start of the curve
          labelX = fromBottom.x + (dx > 0 ? 25 : -25);
          labelY = fromBottom.y + 25;
        }
        
        edgeGroup
          .append("rect")
          .attr("x", labelX - 28)
          .attr("y", labelY - 15)
          .attr("width", 56)
          .attr("height", 30)
          .attr("rx", 6)
          .attr("fill", "#ffffff")
          .attr("stroke", "#475569")
          .attr("stroke-width", 2);
        
        edgeGroup
          .append("text")
          .attr("x", labelX)
          .attr("y", labelY + 1)
          .attr("text-anchor", "middle")
          .attr("dominant-baseline", "middle")
          .attr("fill", "#0f172a")
          .style("font-size", "15px")
          .style("font-weight", "700")
          .text(e.label);
      }
    });

    // draw nodes
    const nodeGroup = svgEl.append("g").attr("class", "nodes");
    const gNodes = nodeGroup.selectAll(".node").data(g.nodes).enter().append("g")
      .attr("class", "node")
      .style("cursor", "pointer")
      .on("click", function(event, d) {
        // Highlight the node temporarily
        d3.select(this).select("rect, polygon").style("opacity", 0.7);
        setTimeout(() => {
          d3.select(this).select("rect, polygon").style("opacity", 1);
        }, 200);
        
        // Call the callback with line number and node data if provided
        if (onNodeClick && d.lineNumber) {
          onNodeClick(d.lineNumber, d);
        }
      });

    // shapes
    gNodes.each(function (d) {
      const node = d3.select(this);
      const x = d.x - nodeWidth / 2;
      const y = d.y - nodeHeight / 2;

      if (d.type === "decision" || d.type === "condition" || d.type === "loop" || d.shape === "diamond") {
        // Diamond for decisions and loops - make it bigger and clearer
        const cx = d.x;
        const cy = d.y;
        const w = 110;
        const h = 50;
        const points = [
          [cx, cy - h],
          [cx + w, cy],
          [cx, cy + h],
          [cx - w, cy],
        ]
          .map((p) => p.join(","))
          .join(" ");
        node
          .append("polygon")
          .attr("points", points)
          .attr("fill", "#fef3c7")
          .attr("stroke", "#f59e0b")
          .attr("stroke-width", 3);
        
        // Text with better wrapping
        const text = d.label || d.text || '';
        const words = text.split(' ');
        const textElement = node
          .append("text")
          .attr("x", d.x)
          .attr("y", d.y)
          .attr("text-anchor", "middle")
          .attr("dominant-baseline", "middle")
          .attr("fill", "#78350f")
          .style("font-size", "14px")
          .style("font-weight", "600");
        
        if (text.length > 15) {
          const mid = Math.ceil(words.length / 2);
          textElement
            .append("tspan")
            .attr("x", d.x)
            .attr("dy", "-0.5em")
            .text(words.slice(0, mid).join(' '));
          textElement
            .append("tspan")
            .attr("x", d.x)
            .attr("dy", "1.2em")
            .text(words.slice(mid).join(' '));
        } else {
          textElement.text(text);
        }
      } else if (d.shape === "stadium" || d.shape === "terminal" || d.type === "start" || d.type === "end") {
        // Terminal shape (rounded rectangle) for Start/End
        node
          .append("rect")
          .attr("x", x)
          .attr("y", y)
          .attr("width", nodeWidth)
          .attr("height", nodeHeight)
          .attr("rx", nodeHeight / 2)
          .attr("ry", nodeHeight / 2)
          .attr("fill", "#dcfce7")
          .attr("stroke", "#16a34a")
          .attr("stroke-width", 3);

        node
          .append("text")
          .attr("x", d.x)
          .attr("y", d.y)
          .attr("text-anchor", "middle")
          .attr("dominant-baseline", "middle")
          .attr("fill", "#14532d")
          .style("font-size", "15px")
          .style("font-weight", "700")
          .text(d.label || d.text || '');
      } else if (d.shape === "parallelogram" || d.type === "io" || d.type === "input" || d.type === "output") {
        // Parallelogram for input/output
        const skewX = 20;
        node
          .append("polygon")
          .attr("points", [
            [x + skewX, y],
            [x + nodeWidth, y],
            [x + nodeWidth - skewX, y + nodeHeight],
            [x, y + nodeHeight],
          ]
            .map((p) => p.join(","))
            .join(" "))
          .attr("fill", "#dbeafe")
          .attr("stroke", "#0284c7")
          .attr("stroke-width", 3);

        // Multi-line text support
        const text = d.label || d.text || '';
        const textElement = node
          .append("text")
          .attr("x", d.x)
          .attr("y", d.y)
          .attr("text-anchor", "middle")
          .attr("dominant-baseline", "middle")
          .attr("fill", "#0c4a6e")
          .style("font-size", "13px")
          .style("font-weight", "600");
        
        if (text.length > 20) {
          const words = text.split(' ');
          const mid = Math.ceil(words.length / 2);
          textElement
            .append("tspan")
            .attr("x", d.x)
            .attr("dy", "-0.4em")
            .text(words.slice(0, mid).join(' '));
          textElement
            .append("tspan")
            .attr("x", d.x)
            .attr("dy", "1.2em")
            .text(words.slice(mid).join(' '));
        } else {
          textElement.text(text);
        }
      } else {
        // Rectangle for process steps
        node
          .append("rect")
          .attr("x", x)
          .attr("y", y)
          .attr("width", nodeWidth)
          .attr("height", nodeHeight)
          .attr("rx", 8)
          .attr("fill", "#f3e8ff")
          .attr("stroke", "#9333ea")
          .attr("stroke-width", 3);

        // Wrap text for long content
        const text = d.label || d.text || '';
        const textElement = node
          .append("text")
          .attr("x", d.x)
          .attr("y", d.y)
          .attr("text-anchor", "middle")
          .attr("dominant-baseline", "middle")
          .attr("fill", "#581c87")
          .style("font-size", "13px")
          .style("font-weight", "600");
        
        if (text.length > 25) {
          const words = text.split(' ');
          const mid = Math.ceil(words.length / 2);
          textElement
            .append("tspan")
            .attr("x", d.x)
            .attr("dy", "-0.4em")
            .text(words.slice(0, mid).join(' '));
          textElement
            .append("tspan")
            .attr("x", d.x)
            .attr("dy", "1.2em")
            .text(words.slice(mid).join(' '));
        } else {
          textElement.text(text);
        }
      }
    });
  }, [graph, code]);

  return (
    <div style={{ width: "100%", height: "100%", minHeight: "400px" }}>
      <svg ref={svgRef} style={{ display: "block", width: "100%", height: "auto", minHeight: "400px" }}></svg>
    </div>
  );
}

export default SvgFlow;
